import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Sequence, Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 256, 'dropout_rate': 0.1,
        'gru_hidden_dim': 256,
        'transformer_layers': 4, 'num_heads': 4, 'transformer_ff_dim': 512
    }

# --- New Backbone: Transformer Encoder ---
class TransformerEncoderBlock(nn.Module):
    d_model: int; num_heads: int; ff_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        # Self-Attention
        h = nn.LayerNorm()(x)
        h = nn.MultiHeadDotProductAttention(num_heads=self.num_heads, qkv_features=self.d_model, dropout_rate=self.dropout_rate)(h, deterministic=deterministic)
        x = x + nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)

        # Feed-Forward
        h = nn.LayerNorm()(x)
        h = nn.Dense(features=self.ff_dim)(h)
        h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        h = nn.Dense(features=self.d_model)(h)
        x = x + nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x

class TransformerFeatureExtractor(nn.Module):
    d_model: int; num_layers: int; num_heads: int; ff_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.Dense(self.d_model)(x)
        for _ in range(self.num_layers):
            h = TransformerEncoderBlock(d_model=self.d_model, num_heads=self.num_heads, ff_dim=self.ff_dim, dropout_rate=self.dropout_rate)(h, deterministic=deterministic)
        return h

# --- Main Network ---
class TransformerRnnNet(nn.Module):
    d_output: int; task_type: str; d_model: int; dropout_rate: float; gru_hidden_dim: int
    transformer_layers: int; num_heads: int; transformer_ff_dim: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        features_seq = TransformerFeatureExtractor(d_model=self.d_model, num_layers=self.transformer_layers, 
                                                   num_heads=self.num_heads, ff_dim=self.transformer_ff_dim, 
                                                   dropout_rate=self.dropout_rate)(x, deterministic=deterministic)

        gru_rnn = nn.RNN(nn.GRUCell(features=self.gru_hidden_dim))
        rnn_output_seq = gru_rnn(features_seq)
        rnn_vec = rnn_output_seq[:, -1, :]

        projected_vec = nn.Dense(features=self.d_model * 2)(rnn_vec)

        z = nn.LayerNorm()(projected_vec)
        z = nn.Dense(self.d_model)(z); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        return logits.squeeze(-1) if self.task_type == 'regression' and self.d_output == 1 else logits

class NetworkWrapper:
    def __init__(self, model_instance): self.network = model_instance
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        return self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
    def apply(self, params, x, deterministic=True, rng_key=None):
        if rng_key is None: rng_key = random.PRNGKey(0)
        return self.network.apply(params, x, deterministic=deterministic, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    model = TransformerRnnNet(d_output=hparams.get("d_output"), task_type=hparams.get("task_type"), d_model=hparams.get("d_model"),
                              dropout_rate=hparams.get("dropout_rate"), gru_hidden_dim=hparams.get("gru_hidden_dim"),
                              transformer_layers=hparams.get("transformer_layers"), num_heads=hparams.get("num_heads"),
                              transformer_ff_dim=hparams.get("transformer_ff_dim"))
    return NetworkWrapper(model)
